// Generates src/data/*.ts from the WHATWG Encoding Standard indexes and the
// Unicode Unihan database. Run once after updating the sources:
//
//   curl -LO https://encoding.spec.whatwg.org/indexes.json
//   curl -LO https://www.unicode.org/Public/UCD/latest/ucd/Unihan.zip && unzip Unihan.zip -d unihan
//   node scripts/gen-data.mjs <dir containing indexes.json and unihan/>
//
// The generated files are committed, so building and testing never need the network.

import { readFileSync, writeFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';

const dir = process.argv[2];
if (!dir) {
  console.error('usage: node scripts/gen-data.mjs <source dir>');
  process.exit(1);
}

const idx = JSON.parse(readFileSync(join(dir, 'indexes.json'), 'utf8'));
const GAP = 0xfffd;

for (const name of ['jis0208', 'jis0212', 'big5', 'gb18030', 'euc-kr', 'windows-1252', 'iso-2022-jp-katakana']) {
  if (idx[name].includes(GAP)) throw new Error(`${name} contains U+FFFD; pick another gap marker`);
}

// Index as a string with one code point per pointer; U+FFFD marks unmapped pointers.
function packIndex(arr) {
  let s = '';
  for (const cp of arr) s += String.fromCodePoint(cp == null ? GAP : cp);
  return JSON.stringify(s);
}

const header = (what) =>
  `// GENERATED by scripts/gen-data.mjs. Do not edit.\n// ${what}\n\n`;

const whatwg =
  header(
    'Source: WHATWG Encoding Standard indexes (https://encoding.spec.whatwg.org/),\n' +
      '// Copyright © WHATWG (Apple, Google, Mozilla, Microsoft), BSD 3-Clause License.\n' +
      '// One code point per pointer; U+FFFD marks a pointer with no code point.',
  ) +
  `export const JIS0208 = ${packIndex(idx['jis0208'])};\n\n` +
  `export const JIS0212 = ${packIndex(idx['jis0212'])};\n\n` +
  `export const BIG5 = ${packIndex(idx['big5'])};\n\n` +
  `export const GB18030 = ${packIndex(idx['gb18030'])};\n\n` +
  `export const EUC_KR = ${packIndex(idx['euc-kr'])};\n\n` +
  `export const WINDOWS_1252 = ${packIndex(idx['windows-1252'])};\n\n` +
  `export const ISO_2022_JP_KATAKANA = ${packIndex(idx['iso-2022-jp-katakana'])};\n\n` +
  `/** [pointer, code point] pairs, sorted by pointer. */\n` +
  `export const GB18030_RANGES: ReadonlyArray<readonly [number, number]> = ${JSON.stringify(idx['gb18030-ranges'])};\n`;

writeFileSync('src/data/whatwg.ts', whatwg);

// ---- Han character tiers ----
// Tier 1: everyday characters (Japanese Jōyō kanji, the first 3500 of China's
// Table of General Standard Chinese Characters, Hong Kong primary-school list),
// split by how many everyday lists include them (1A: three or more, 1B: two, 1C: one).
// Tier 2: still common (rest of TGH level 2, Jinmeiyō, Korean education hanja,
// JIS X 0208 level 1, GB2312 level 1, Big5 "frequently used" block).
// On top of the tiers, kHanyuPinlu (counts from a modern Chinese frequency
// dictionary) gives log2 frequencies for the most common characters; they are
// copied to traditional, semantic and Z variants so that 說/説/说 all count.

const unihanDir = join(dir, 'unihan');
const props = new Map(); // prop -> Map<cp, value>
for (const f of readdirSync(unihanDir)) {
  if (!f.endsWith('.txt')) continue;
  for (const line of readFileSync(join(unihanDir, f), 'utf8').split('\n')) {
    if (!line.startsWith('U+')) continue;
    const [u, prop, value] = line.split('\t');
    if (
      ![
        'kJoyoKanji',
        'kTGH',
        'kGradeLevel',
        'kJinmeiyoKanji',
        'kKoreanEducationHanja',
        'kHanyuPinlu',
        'kTraditionalVariant',
        'kSimplifiedVariant',
        'kSemanticVariant',
        'kZVariant',
      ].includes(prop)
    )
      continue;
    if (!props.has(prop)) props.set(prop, new Map());
    props.get(prop).set(parseInt(u.slice(2), 16), value.trim());
  }
}

// Membership count across everyday-character lists, as a rough frequency proxy.
// The national lists (Jōyō, TGH) count double so that common characters used in
// only one region (simplified-only hanzi, Japanese-only kanji) still rank high.
const count = new Map();
const bump = (cp) => count.set(cp, (count.get(cp) ?? 0) + 1);
const t1 = new Set();
const t2 = new Set();
for (const [cp, v] of props.get('kJoyoKanji')) if (/^\d{4}$/.test(v)) (t1.add(cp), bump(cp), bump(cp));
for (const [cp, v] of props.get('kTGH')) {
  const n = Math.min(...v.split(' ').map((x) => parseInt(x.split(':')[1], 10)));
  if (n <= 3500) (t1.add(cp), bump(cp), bump(cp));
  else if (n <= 6500) t2.add(cp);
}
for (const [cp, v] of props.get('kGradeLevel')) {
  t1.add(cp);
  bump(cp);
  if (parseInt(v, 10) <= 3) bump(cp);
}
for (const cp of props.get('kKoreanEducationHanja').keys()) (t2.add(cp), bump(cp));
for (const cp of props.get('kJinmeiyoKanji').keys()) t2.add(cp);

// JIS X 0208 level 1 kanji: rows 16-47.
idx['jis0208'].slice(15 * 94, 47 * 94).forEach((cp) => cp != null && t2.add(cp));
// GB2312 level 1 hanzi: GBK lead 0xB0-0xD7, trail 0xA1-0xFE.
for (let lead = 0xb0; lead <= 0xd7; lead++)
  for (let trail = 0xa1; trail <= 0xfe; trail++) {
    const cp = idx['gb18030'][(lead - 0x81) * 190 + (trail - 0x41)];
    if (cp != null) t2.add(cp);
  }
// Big5 frequently used characters: 0xA440-0xC67E.
for (let p = (0xa4 - 0x81) * 157; p <= (0xc6 - 0x81) * 157 + (0x7e - 0x40); p++) {
  const cp = idx['big5'][p];
  if (cp != null) t2.add(cp);
}
for (const cp of t1) t2.delete(cp);

// ---- Frequencies ----
const freq = new Map();
let total = 0;
for (const [cp, v] of props.get('kHanyuPinlu')) {
  let n = 0;
  for (const m of v.matchAll(/\((\d+)\)/g)) n += parseInt(m[1], 10);
  freq.set(cp, n);
  total += n;
}
const variants = (prop, cp) =>
  [...new Set([...(props.get(prop).get(cp) ?? '').matchAll(/U\+([0-9A-F]+)/g)].map((m) => parseInt(m[1], 16)))].filter(
    (v) => v !== cp && t1.has(v),
  );
for (const [cp, n] of [...freq]) {
  const give = (v, share) => {
    if ((freq.get(v) ?? 0) < share) freq.set(v, share);
  };
  for (const prop of ['kTraditionalVariant', 'kSimplifiedVariant']) {
    const vs = variants(prop, cp);
    // One-to-many mappings (发 -> 發/髮): each form gets a quarter of the count.
    for (const v of vs) give(v, vs.length > 1 ? n / 4 : n);
  }
  for (const prop of ['kSemanticVariant', 'kZVariant']) for (const v of variants(prop, cp)) give(v, n / 4);
}
// Quantize log2 frequency to 0.25 bits; keep characters more frequent than ~1 in 30000.
const bins = new Map();
for (const [cp, n] of freq) {
  const w = Math.round(Math.log2((n + 1) / total) * 4) / 4;
  if (w < -15) continue;
  if (!bins.has(w)) bins.set(w, []);
  bins.get(w).push(cp);
}
const freqTable = [...bins]
  .sort((a, b) => b[0] - a[0])
  .map(([w, cps]) => `[${w}, ${JSON.stringify(cps.sort((a, b) => a - b).map((c) => String.fromCodePoint(c)).join(''))}]`)
  .join(',\n  ');

const isHan = (cp) =>
  (cp >= 0x3400 && cp <= 0x9fff) || (cp >= 0xf900 && cp <= 0xfaff) || (cp >= 0x20000 && cp <= 0x3134f);
const packSet = (set) =>
  JSON.stringify(
    [...set]
      .filter(isHan)
      .sort((a, b) => a - b)
      .map((cp) => String.fromCodePoint(cp))
      .join(''),
  );

const han =
  header(
    'Han character frequency tiers derived from the Unicode Unihan database\n' +
      '// (kJoyoKanji, kTGH, kGradeLevel, kJinmeiyoKanji, kKoreanEducationHanja, kHanyuPinlu, variants),\n' +
      '// © Unicode, Inc., Unicode License v3, plus the WHATWG indexes.',
  ) +
  `export const HAN_TIER1A = ${packSet(new Set([...t1].filter((cp) => count.get(cp) >= 3)))};\n\n` +
  `export const HAN_TIER1B = ${packSet(new Set([...t1].filter((cp) => count.get(cp) === 2)))};\n\n` +
  `export const HAN_TIER1C = ${packSet(new Set([...t1].filter((cp) => count.get(cp) <= 1)))};\n\n` +
  `export const HAN_TIER2 = ${packSet(t2)};\n\n` +
  `/** [log2 frequency, characters] from kHanyuPinlu, most frequent first. */\n` +
  `export const HAN_FREQ: ReadonlyArray<readonly [number, string]> = [\n  ${freqTable},\n];\n`;

writeFileSync('src/data/han.ts', han);
const n = (k) => [...t1].filter((cp) => (k === 3 ? count.get(cp) >= 3 : k === 1 ? count.get(cp) <= 1 : count.get(cp) === k)).length;
console.log(`whatwg.ts ${whatwg.length} chars; han.ts tier1a=${n(3)} tier1b=${n(2)} tier1c=${n(1)} tier2=${t2.size}`);
